-- 001: contacts, lists, tags, consent, suppressions, API keys, idempotency.
-- Conventions: IDs are prefixed ULIDs generated by the app; timestamps are
-- UTC ISO-8601 strings; JSON is stored as TEXT and never queried inside.

CREATE TABLE api_keys (
    id           TEXT PRIMARY KEY,
    name         TEXT NOT NULL,
    prefix       TEXT NOT NULL,           -- first characters, shown so owners can tell keys apart
    key_hash     TEXT NOT NULL UNIQUE,    -- SHA-256 of the full key; the key itself is never stored
    scopes       TEXT NOT NULL,           -- space-separated: read write send
    created_at   TEXT NOT NULL,
    last_used_at TEXT,
    revoked_at   TEXT
);

CREATE TABLE contacts (
    id         TEXT PRIMARY KEY,
    email      TEXT NOT NULL UNIQUE,      -- normalised to lower case
    first_name TEXT NOT NULL DEFAULT '',
    last_name  TEXT NOT NULL DEFAULT '',
    fields     TEXT NOT NULL DEFAULT '{}', -- custom fields for personalisation only
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE contact_tags (
    contact_id TEXT NOT NULL REFERENCES contacts (id) ON DELETE CASCADE,
    tag        TEXT NOT NULL,             -- normalised to lower case
    PRIMARY KEY (contact_id, tag)
);
CREATE INDEX contact_tags_by_tag ON contact_tags (tag, contact_id);

CREATE TABLE lists (
    id            TEXT PRIMARY KEY,
    name          TEXT NOT NULL UNIQUE COLLATE NOCASE,
    description   TEXT NOT NULL DEFAULT '',
    double_opt_in INTEGER NOT NULL DEFAULT 1 CHECK (double_opt_in IN (0, 1)),
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL
);

CREATE TABLE list_members (
    list_id         TEXT NOT NULL REFERENCES lists (id) ON DELETE CASCADE,
    contact_id      TEXT NOT NULL REFERENCES contacts (id) ON DELETE CASCADE,
    status          TEXT NOT NULL CHECK (status IN ('pending', 'subscribed', 'unsubscribed')),
    subscribed_at   TEXT,
    unsubscribed_at TEXT,
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL,
    PRIMARY KEY (list_id, contact_id)
);
CREATE INDEX list_members_by_contact ON list_members (contact_id);
CREATE INDEX list_members_by_status ON list_members (list_id, status, contact_id);

-- Append-only record of how each address came to be on a list, and how it left.
-- Kept for compliance (Spam Act 2003, GDPR); removed only when the contact is erased.
CREATE TABLE consent_events (
    id         TEXT PRIMARY KEY,
    contact_id TEXT NOT NULL REFERENCES contacts (id) ON DELETE CASCADE,
    list_id    TEXT,                      -- NULL for events not tied to a list
    action     TEXT NOT NULL CHECK (action IN ('consent', 'confirm', 'unsubscribe')),
    source     TEXT NOT NULL,             -- e.g. "signed up on website", "API", "CSV import: customers.csv"
    ip         TEXT,
    created_at TEXT NOT NULL
);
CREATE INDEX consent_events_by_contact ON consent_events (contact_id, created_at);

-- Addresses that must never be sent marketing email, across every list.
-- Keyed by address so a suppression outlives deletion of the contact.
CREATE TABLE suppressions (
    email      TEXT PRIMARY KEY,
    reason     TEXT NOT NULL CHECK (reason IN ('bounce', 'complaint', 'manual')),
    detail     TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL
);

-- Stored responses for requests sent with an Idempotency-Key header (kept 24 hours).
CREATE TABLE idempotency_keys (
    api_key_id  TEXT NOT NULL,
    key         TEXT NOT NULL,
    fingerprint TEXT NOT NULL,            -- hash of method, path and body
    status_code INTEGER NOT NULL,
    body        TEXT NOT NULL,
    created_at  TEXT NOT NULL,
    PRIMARY KEY (api_key_id, key)
);
CREATE INDEX idempotency_keys_by_age ON idempotency_keys (created_at);
